insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p71', 'allemand', '3AS', 13, 71, 'L4 3AS p71 — Umweltprobleme (ouverture : die frierende Erde · Müll · tote Bäume im Smog)', E'Lektion 4 — Umweltprobleme (ouverture)\nCartoon : die Erde friert (Mütze + Schal).\nFotos : ein Kind zwischen Müll und Abfällen · tote Bäume im Smog/Nebel.\nThema : die neuen Umweltprobleme, die unsere Existenz bedrohen.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p72', 'allemand', '3AS', 13, 72, 'L4 3AS p72 — Um uns die Umwelt (Text : Umwelt formt Charakter · Fortschritt darf Umwelt nicht zerstören)', E'1. Was fällt Ihnen ein zu Umwelt ?\nUm uns die Umwelt\n2. Lesen Sie den Text.\nWenn wir auf die Welt kommen, kommen wir gleichzeitig in eine «Umwelt», die Welt, die uns umgibt. Das sind die Menschen, mit denen wir zu tun haben. Das ist aber auch unsere Wohnung, das Wohngebiet, in dem das Haus steht. Die Stadt oder das Dorf, in dem sich das Wohngebiet befindet.\nDiese Umwelt formt unseren Charakter, beeinflusst unsere Lebenschancen.\nWenn man von Umweltschutz spricht, so ist damit gemeint, der technische Fortschritt darf nicht einfach eine natürlich gewachsene Umwelt rücksichtslos zerstören.\nDiese Gefahr besteht in allen Ländern.\nDie Menschen brauchen sauberes Wasser, saubere Luft, Wälder und Felder, um leben zu können.\nFabriken verschmutzen Luft und Wasser. Autobahnen verdrängen die Wälder und Felder…\nFabriken produzieren aber auch wichtige Dinge.\nAutobahnen machen bequeme und schnelle Reisen möglich. Niemand kann und will sie abschaffen.\nBeim Wort Umweltschutz denkt man nicht nur an die kleine Umwelt jedes Einzelnen, sondern auch an die Erhaltung und Verbesserung des Lebensraumes ganzer Regionen.\nFotos : Autoverkehr auf einer Autobahn · Fabrik mit rauchenden Schornsteinen.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p73', 'allemand', '3AS', 13, 73, 'L4 3AS p73 — Stimmt das ? + Ergänzen + Synonyme + Antworten + Übersetzen + Substantive mit -ung', E'3. Stimmt das, stimmt das nicht ? Kreuzen Sie an. (R/F)\n- Die Umwelt ist alles, was uns umgibt.\n- Die Umwelt beeinflusst unser Denken und Verhalten.\n- Der technische Fortschritt achtet nicht auf die Umwelt.\n- Reines Wasser, reine Luft sind notwendig für das Leben.\n- Der technische Fortschritt hat nicht nur negative Folgen.\n4. Ergänzen Sie. (schnell und bequem · Umweltschutz · verdrängen · Umwelt · sich befinden)\n- Jeder von uns sollte an seine … denken.\n- Unser Dorf … … in der Nähe einer Fabrik, die die Umwelt verschmutzt.\n- Die Menschen müssen Interesse am … haben.\n- Autobahnen … die Wälder.\n- Heutzutage reist man … und …\n5. Ersetzen Sie die unterstrichenen Wörter durch Synonyme aus dem Text.\n- Was machen Sie für den Umweltschutz ?\n- Die Kläranlagen liegen außerhalb der Stadt.\n- Der Mensch muss reine Luft atmen.\n- Die Betriebe stellen nützliche Dinge her.\n- Die Fabrikbesitzer müssen unsere Umwelt bewahren.\n6. Antworten Sie.\n1. Was ist die Umwelt ?\n2. Welche Rolle spielt die Umwelt in unserem Leben ?\n3. Wozu brauchen die Menschen eine saubere Umwelt ?\n4. Warum haben die Fabriken sowohl eine positive als auch eine negative Rolle ?\n5. Welches sind die Aufgaben des Umweltschutzes ?\n7. Übersetzen Sie ins Arabische.\nDie Umwelt formt unseren Charakter und beeinflusst unsere Lebenschancen.\n8. Bilden Sie Substantive mit -ung wie im Beispiel.\nBeispiel : erhalten + ung → die Erhaltung · zerstören · verschmutzen + ung → …', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p74', 'allemand', '3AS', 13, 74, 'L4 3AS p74 — Die Umwelt die uns umgibt : Relativpronomen + Tabelle Nominativ/Akkusativ', E'8. (suite) : verdrängen · erfinden · entwickeln · meinen · ordnen · retten + ung → …\nDie Umwelt, die uns umgibt…\n1. Üben Sie zu zweit wie im Beispiel.\n- Die Umwelt, die uns umgibt, ist in Gefahr.\n- Ja, der technische Fortschritt, den der Mensch entwickelt hat, gefährdet die Umwelt.\nWörter : die Umwelt · der Wald · die Natur · die Flora · der technische Fortschritt · die Industrie · das Wachstum · die Atomkraftwerke · der Mensch/entwickeln · die Wirtschaft/brauchen · die Welt/benötigen · die Konzerne/bauen\n2. Ergänzen Sie die Tabelle. (Maskulinum/Neutrum/Femininum/Plural × Nominativ/Akkusativ : die · den)\n3. Ergänzen Sie das Relativpronomen.\n- Die Luft, … wir atmen, ist unrein.\n- Der Wald, … wir zur Erholung brauchen, ist gefährdet.\n- Die Industrie, … die Wirtschaft fördert, ist wichtig für das Land.\n- Der Baum, … auf der Wiese steht, ist krank.\n- Das Windrad, … die Firma montiert, ist nicht schädlich für die Umwelt.\n- Die Wälder, … der Mensch nicht schützt, sind in Gefahr.\n- Das Ozon, … die Erde vor zu starken Sonnenstrahlen bewahrt, ist heute bedroht.\n- Die Leute, … die Natur schützen, sind umweltfreundlich.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p75', 'allemand', '3AS', 13, 75, 'L4 3AS p75 — Der Umweltschutz (Text + R/F + Zusammensetzungen Umwelt + Ergänzen)', E'Der Umweltschutz\nLuftverschmutzung, Tierarten, die aussterben, verschmutzte Meere und Flüsse, Klimaerwärmung und Atommüll sind die neuen Umweltprobleme, die unsere Existenz bedrohen.\nPolitiker und Fachleute diskutieren und die Zeitungen berichten fast täglich darüber.\nUnd ganz in unserer Nähe ?\nGiftiger Rauch aus Fabriken und Industrieanlagen, Autoabgase verursachen Smog, Straßen zerstören die Lebensräume von Tieren und Pflanzen. Müllberge wachsen immer höher, was zur Zerstörung des Ökosystems führt.\nDeshalb müssen sich die Menschen für den Schutz von Natur und Umwelt mit praktischen Maßnahmen ebenso wie mit politischen Aktionen einsetzen wie zum Beispiel :\n- die Reinhaltung des Wassers und der Luft, d.h. Schutz vor Abgasen und Abwässern.\n- die Bekämpfung des Lärms, d.h. Schutz vor den Geräuschen, die durch Motoren und Maschinen verursacht werden.\n- die unschädliche Beseitigung von Müll und giftigen Industrieabfällen.\n- die Reinhaltung der Nahrung, d.h. Schutz vor schädlichem Gebrauch chemischer Mittel.\n- den Menschen zu einem umweltfreundlichen Denken und Verhalten erziehen.\n- strenge Maßnahmen gegen die Umweltverschmutzung treffen.\nSo kann man unseren schönen blauen Planeten retten.\n1. Richtig oder falsch ? Kreuzen Sie an. (R/F)\n- Das Leben auf dem Planeten ist in Gefahr.\n- Die Industriewerke sind «umweltfreundlich».\n- Die Menschen müssen ihre Umwelt schützen.\n- Die Reinhaltung des Wassers, der Luft und der Nahrung ist keine Priorität.\n2. Bilden Sie Zusammensetzungen mit «Umwelt». Beispiel : die Umweltkatastrophe\n3. Ergänzen Sie. (giftig · aussterben · Luftverschmutzung · verursachen · verschmutzt)\n- Heutzutage gibt es viele Atembeschwerden wegen …\n- Die Flugzeuge … Lärm und Abgase.\n- Die chemischen Produkte sind … für die Wasserpflanzen.\n- In einer … See können sich die Leute nicht baden.\n- Wegen der Abwässer … viele Fische …', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
